use vstd::prelude::*;

verus! {

spec fn all_less_than(n: int, s: Seq<int>) -> bool {
    forall|i: int| 0 <= i < s.len() ==> n > s[i]
}

fn is_greater(n: i32, a: &Vec<i32>) -> (res: bool)
    ensures
        res == all_less_than(n as int, a@.map_values(|x: i32| x as int)),
{
    // Array is assumed non-empty, but this works correctly even if it were empty.
    for &x in a.iter()
        invariant
            // The loop has examined some prefix of the vector, and `res` would be
            // `false` iff there exists an examined element >= n. Since this loop
            // returns early on failure, while we are still in the loop we know
            // n is greater than all examined elements.
            forall|i: int|
                0 <= i < a@.len() - (a.iter().count() as int) ==> n as int > (a@[i] as int)
    {
        if n <= x {
            return false;
        }
    }
    true
}

} // verus!

